effect.shader:
float hash2(vec2 c) {
    c += vec2(float(seed) * 13.7);
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

/** A distância de um ponto p ao segmento `a → b` (SDF 2D canônico). */
float distanciaAoSegmento(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-8), 0.0, 1.0);
    return length(pa - ba * h);
}

/** O traço de uma gota dentro de uma célula. Retorna a intensidade em `uvDaTela`. */
float gotaDaCelula(vec2 celula, vec2 uvDaTela, float t) {
    // Posição x da gota dentro da célula (hash estável).
    float xDaGota = hash2(celula + 0.1);
    float yFase = hash2(celula + 0.3);
    float tamanho = mix(0.5, 1.2, hash2(celula + 0.7));

    // Y cai no tempo, recomeça ao sair.
    float y = fract(yFase + t);
    vec2 topoDaGota = vec2(xDaGota, 1.0 - y);
    vec2 baseDaGota = topoDaGota - vec2(0.0, streakLength);

    // Vento inclina o segmento: gira em volta do topo.
    float a = radians(wind);
    vec2 d = baseDaGota - topoDaGota;
    d = vec2(d.x * cos(a) - d.y * sin(a), d.x * sin(a) + d.y * cos(a));
    baseDaGota = topoDaGota + d;

    float dist = distanciaAoSegmento(uvDaTela, topoDaGota, baseDaGota);
    float largura = 0.0015 * thickness * tamanho;
    return (1.0 - smoothstep(0.0, largura, dist)) * tamanho;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 grade = vec2(density * 0.1, density * 0.3);
    vec2 escalado = acScreenNorm * grade;
    vec2 i = floor(escalado);
    vec2 f = fract(escalado);
    float t = acTime * speed;

    // Olha a célula atual + algumas vizinhas acima (o traço pode atravessar).
    float melhor = 0.0;
    for (int dy = 0; dy <= 2; dy++) {
        vec2 celula = i + vec2(0.0, float(dy));
        melhor = max(melhor, gotaDaCelula(celula, f - vec2(0.0, float(dy)), t));
    }

    float alfa = clamp(melhor * intensity, 0.0, 1.0) * rainColor.a;

    vec3 cor = mix(original.rgb, rainColor.rgb, alfa);
    float alfaFinal = max(original.a, alfa);

    fragColor = vec4(cor, alfaFinal);
}
